import math

def add(a, b):
    return [x + y for x, y in zip(a, b)]

def scale(k, v):
    return [k * x for x in v]

def norm(v):
    return math.sqrt(sum(x * x for x in v))

import math

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def cosine(a, b):
    na = math.sqrt(dot(a, a))
    nb = math.sqrt(dot(b, b))
    if na == 0 or nb == 0:
        return 0.0
    return dot(a, b) / (na * nb)

