code.solution:
import math

def mean(data):
    return sum(data) / len(data)

def variance(data):
    m = mean(data)
    return sum((x - m) ** 2 for x in data) / len(data)

def std(data):
    return math.sqrt(variance(data))

def zscores(data):
    m = mean(data)
    s = std(data)
    if s == 0:
        return [0.0 for _ in data]
    return [(x - m) / s for x in data]

import math

def softmax(scores):
    m = max(scores)
    exps = [math.exp(s - m) for s in scores]
    total = sum(exps)
    return [e / total for e in exps]

def log_loss(probs, correct):
    p = max(probs[correct], 1e-12)
    return -math.log(p)
